const __pageData = JSON.parse('{"title":"Mike Johnson","description":"","frontmatter":{"title":"Mike Johnson","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["politician","congress","republican","house-speaker"],"sources":["raw/a-glaring-double-standard.md","raw/badlands-brief-05f.md","raw/badlands-brief-1ae.md","raw/badlands-brief-285.md","raw/badlands-brief-314.md","raw/badlands-brief-52f.md","raw/badlands-brief-ac2.md","raw/badlands-brief-fd9.md","raw/badlands-news-brief-02f.md","raw/badlands-news-brief-0cd.md","raw/badlands-news-brief-0be.md","raw/badlands-news-brief-0db.md","raw/badlands-news-brief-0c1.md","raw/badlands-news-brief-10a.md","raw/badlands-news-brief-0b0.md","raw/badlands-news-brief-0ef.md","raw/badlands-news-brief-116.md","raw/badlands-news-brief-143.md","raw/badlands-news-brief-168.md","raw/badlands-news-brief-169.md","raw/badlands-news-brief-1ab.md","raw/badlands-news-brief-1d1.md","raw/badlands-news-brief-204.md","raw/badlands-news-brief-215.md","raw/badlands-news-brief-24e.md","raw/badlands-news-brief-2db.md","raw/badlands-news-brief-32c.md","raw/badlands-news-brief-365.md","raw/badlands-news-brief-357.md","raw/badlands-news-brief-4b3.md","raw/badlands-news-brief-505.md","raw/badlands-news-brief-553.md","raw/badlands-news-brief-5ff.md","raw/badlands-news-brief-6b1.md","raw/badlands-news-brief-6d2.md","raw/badlands-news-brief-6e6.md","raw/badlands-news-brief-73f.md","raw/badlands-news-brief-752.md","raw/badlands-news-brief-79f.md","raw/badlands-news-brief-8a4.md","raw/badlands-news-brief-860.md"],"confidence":"low"},"headers":[],"relativePath":"entities/mike-johnson.md","filePath":"entities/mike-johnson.md","lastUpdated":null}');
